using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidResearchLaunchDraft(string DraftFingerprint,string DatasetSelectionFingerprint,string StrategySelectionFingerprint,string DatasetFingerprint,string StrategyFingerprint,bool Ready,bool CanSubmitOrders);public static class AndroidResearchLaunchDraftRules{public static AndroidResearchLaunchDraft Create(AndroidDatasetSelection dataset,AndroidStrategySelection strategy,AndroidResearchReadinessCard readiness){if(dataset.DatasetFingerprint!=readiness.DatasetFingerprint||strategy.StrategyFingerprint!=readiness.StrategyFingerprint)throw new InvalidOperationException("Android research launch draft identities do not match readiness evidence.");if(!readiness.Ready)throw new InvalidOperationException("Android research launch draft requires complete readiness.");var text=string.Join("|",dataset.SelectionFingerprint,strategy.SelectionFingerprint,readiness.DatasetFingerprint,readiness.StrategyFingerprint);var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,dataset.SelectionFingerprint,strategy.SelectionFingerprint,dataset.DatasetFingerprint,strategy.StrategyFingerprint,true,false);}}
